import { useState, useEffect, useCallback } from 'react'
import { DataTable, type DataTableColumn } from '@/components/ui/DataTable.js'
import { CurrencyInput } from '@/components/ui/CurrencyInput.js'
import { Button } from '@/components/ui/button.js'
import { Input } from '@/components/ui/input.js'
import { Label } from '@/components/ui/label.js'
import { Textarea } from '@/components/ui/textarea.js'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog.js'
import { formatCentsToEuro } from '@/shared/lib/utils.js'
import { showSuccess, showError } from '@/shared/lib/notifications.js'
import { Wrench } from 'lucide-react'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface LaborServiceCatalogItem extends Record<string, unknown> {
  id: string
  name: string
  defaultRate: number
}

interface LaborServiceDetail extends LaborServiceCatalogItem {
  description?: string
  billingType: 'hourly'
}

interface CreateLaborServiceInput {
  name: string
  description?: string
  billingType: 'hourly'
  defaultRate: number
}

interface UpdateLaborServiceInput {
  name?: string
  description?: string
  billingType?: 'hourly'
  defaultRate?: number
}

// ---------------------------------------------------------------------------
// API helpers
// ---------------------------------------------------------------------------

async function fetchLaborServices(search?: string): Promise<{ laborServices: LaborServiceCatalogItem[]; total: number }> {
  const url = search ? `/api/repairs/labor-services?search=${encodeURIComponent(search)}` : '/api/repairs/labor-services'
  const res = await fetch(url)
  if (!res.ok) throw new Error('Failed to fetch labor services')
  return res.json()
}

async function createLaborService(input: CreateLaborServiceInput): Promise<LaborServiceDetail> {
  const res = await fetch('/api/repairs/labor-services', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to create labor service')
  }
  return res.json()
}

async function updateLaborService(id: string, input: UpdateLaborServiceInput): Promise<LaborServiceDetail> {
  const res = await fetch(`/api/repairs/labor-services/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to update labor service')
  }
  return res.json()
}

async function deactivateLaborService(id: string): Promise<void> {
  const res = await fetch(`/api/repairs/labor-services/${id}/deactivate`, { method: 'PATCH' })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to deactivate labor service')
  }
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function LaborServicesPage() {
  const [laborServices, setLaborServices] = useState<LaborServiceCatalogItem[]>([])
  const [totalItems, setTotalItems] = useState(0)
  const [searchTerm, setSearchTerm] = useState('')
  const [currentPage, setCurrentPage] = useState(1)
  const pageSize = 20

  // Modal state
  const [modalOpen, setModalOpen] = useState(false)
  const [editingService, setEditingService] = useState<LaborServiceDetail | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [deactivatingId, setDeactivatingId] = useState<string | null>(null)

  // Form state
  const [formName, setFormName] = useState('')
  const [formDescription, setFormDescription] = useState('')
  const [formDefaultRate, setFormDefaultRate] = useState(0)

  // Fetch labor services on search/page change
  useEffect(() => {
    let cancelled = false
    fetchLaborServices(searchTerm || undefined).then(({ laborServices: ls, total }) => {
      if (!cancelled) {
        setLaborServices(ls)
        setTotalItems(total)
      }
    }).catch((err) => showError(err.message))

    return () => { cancelled = true }
  }, [searchTerm, currentPage])

  // Reset page when search changes
  const handleSearchChange = useCallback((term: string) => {
    setSearchTerm(term)
    setCurrentPage(1)
  }, [])

  // Open create modal
  const openCreateModal = () => {
    setEditingService(null)
    resetForm()
    setModalOpen(true)
  }

  // Open edit modal
  const openEditModal = (service: LaborServiceCatalogItem) => {
    fetch(`/api/repairs/labor-services/${service.id}`)
      .then(res => res.json())
      .then((detail: LaborServiceDetail) => {
        setEditingService(detail)
        setFormName(detail.name)
        setFormDescription(detail.description ?? '')
        setFormDefaultRate(detail.defaultRate)
        setModalOpen(true)
      })
      .catch((err) => showError(err.message))
  }

  // Close modal and reset form
  const closeModal = () => {
    setModalOpen(false)
    setEditingService(null)
    resetForm()
  }

  const resetForm = () => {
    setFormName('')
    setFormDescription('')
    setFormDefaultRate(0)
  }

  // Submit form (create or update)
  const handleSubmit = async () => {
    if (!formName.trim()) {
      showError('Name is required')
      return
    }
    if (formDefaultRate <= 0) {
      showError('Hourly rate must be greater than 0')
      return
    }

    setSubmitting(true)
    try {
      if (editingService) {
        // Update existing service
        await updateLaborService(editingService.id, {
          name: formName.trim(),
          description: formDescription.trim() || undefined,
          defaultRate: formDefaultRate,
        })
        showSuccess('Labor service updated')
      } else {
        // Create new service (billingType is always 'hourly', hidden from UI)
        await createLaborService({
          name: formName.trim(),
          description: formDescription.trim() || undefined,
          billingType: 'hourly' as const,
          defaultRate: formDefaultRate,
        })
        showSuccess('Labor service created')
      }
      closeModal()
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to save labor service')
    } finally {
      setSubmitting(false)
    }
  }

  // Deactivate service with confirmation
  const handleDeactivate = async (service: LaborServiceCatalogItem) => {
    if (!confirm(`Deactivate "${service.name}"? This cannot be undone.`)) return

    setDeactivatingId(service.id)
    try {
      await deactivateLaborService(service.id)
      showSuccess('Labor service deactivated')
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to deactivate labor service')
    } finally {
      setDeactivatingId(null)
    }
  }

  // Column definitions for the DataTable
  const columns: DataTableColumn<LaborServiceCatalogItem>[] = [
    {
      key: 'name',
      header: 'Name',
      render: (item) => <span className="font-medium">{item.name}</span>,
    },
    {
      key: 'defaultRate',
      header: 'Hourly Rate',
      render: (item) => formatCentsToEuro(item.defaultRate),
    },
    {
      key: 'actions',
      header: '',
      render: (item) => (
        <div className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={() => openEditModal(item)}>Edit</Button>
          <Button
            variant="ghost"
            size="sm"
            className="text-red-500 hover:text-red-600"
            disabled={deactivatingId === item.id}
            onClick={() => handleDeactivate(item)}
          >
            {deactivatingId === item.id ? '...' : 'Deactivate'}
          </Button>
        </div>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <Wrench size={24} />
          Labor Services
        </h1>
        <Button onClick={openCreateModal}>Add Service</Button>
      </div>

      {/* DataTable */}
      <DataTable<LaborServiceCatalogItem>
        data={laborServices}
        columns={columns}
        searchTerm={searchTerm}
        onSearchChange={handleSearchChange}
        totalItems={totalItems}
        currentPage={currentPage}
        pageSize={pageSize}
        onPageChange={(page) => {
          if (page >= 1 && page <= Math.ceil(totalItems / pageSize)) {
            setCurrentPage(page)
          }
        }}
        emptyMessage={'No labor services found. Click "Add Service" to create one.'}
      />

      {/* Create/Edit Modal */}
      <Dialog open={modalOpen} onOpenChange={(open) => !open && closeModal()}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{editingService ? 'Edit Labor Service' : 'Add New Labor Service'}</DialogTitle>
            <DialogDescription>
              {editingService
                ? `Editing ${editingService.name}`
                : 'Fill in the details for the new labor service.'}
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            {/* Name */}
            <div className="space-y-2">
              <Label htmlFor="name">Name *</Label>
              <Input
                id="name"
                value={formName}
                onChange={(e) => setFormName(e.target.value)}
                placeholder="e.g. Standard Repair"
              />
            </div>

            {/* Description */}
            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={formDescription}
                onChange={(e) => setFormDescription(e.target.value)}
                placeholder="Optional description"
                rows={2}
              />
            </div>

            {/* Billing Type — hidden (always hourly), shown for clarity */}
            <div className="space-y-2">
              <Label htmlFor="billingType">Billing Type</Label>
              <Input id="billingType" value="Hourly" disabled className="bg-muted" />
            </div>

            {/* Hourly Rate */}
            <div className="space-y-2">
              <Label htmlFor="defaultRate">Default Rate (€/hr) *</Label>
              <CurrencyInput
                id="defaultRate"
                value={formDefaultRate}
                onChange={setFormDefaultRate}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={closeModal}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={submitting}>
              {submitting ? 'Saving...' : editingService ? 'Save Changes' : 'Create Service'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import { Hono } from 'hono'
import { z } from 'zod'
import { zValidator } from '@hono/zod-validator'
import {
  browseTemplates,
  createTemplate,
  updateTemplate,
  deactivateTemplate,
  getTemplateById,
  type CreateBicycleTemplateInput,
} from '../services/bicycle-template.service.js'
import { TemplateNotFoundError } from '../services/bicycle-template.service.js'

const bicycleTemplatesRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /bicycle-templates — Browse the active bicycle template catalog
// ===========================================================================

/**
 * Query params:
 *   - search (optional) — Filter by brand or model (case-insensitive partial match)
 */
bicycleTemplatesRoutes.get('/', async (c) => {
  const search = c.req.query('search')
  const result = await browseTemplates(search || undefined)
  return c.json(result)
})

// ---------------------------------------------------------------------------
// GET /bicycle-templates/:id — Get a single template detail
// ===========================================================================

bicycleTemplatesRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')
  const template = await getTemplateById(id)

  if (!template) {
    return c.json({ error: 'Bicycle template not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json(template)
})

// ---------------------------------------------------------------------------
// POST /bicycle-templates — Create a new bicycle template
// ===========================================================================

const createSchema = z.object({
  brand: z.string().min(1, 'Brand is required').max(200),
  model: z.string().min(1, 'Model is required').max(200),
  description: z.string().max(1000).optional(),
  basePriceNet: z.number().int().nonnegative('Base price must be non-negative').optional(),
})

bicycleTemplatesRoutes.post('/', zValidator('json', createSchema), async (c) => {
  const input: CreateBicycleTemplateInput = c.req.valid('json')
  try {
    const template = await createTemplate(input)
    return c.json(template, 201)
  } catch (err) {
    console.error('[POST /bicycle-templates] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /bicycle-templates/:id — Update a template (partial update allowed)
// ===========================================================================

const updateSchema = z.object({
  brand: z.string().min(1).max(200).optional(),
  model: z.string().min(1).max(200).optional(),
  description: z.string().max(1000).optional(),
  basePriceNet: z.number().int().nonnegative('Base price must be non-negative').optional(),
}).refine(data => Object.keys(data).length > 0, {
  message: 'At least one field must be provided for update'
})

bicycleTemplatesRoutes.patch('/:id', zValidator('json', updateSchema), async (c) => {
  const id = c.req.param('id')

  try {
    const input = c.req.valid('json')
    const template = await updateTemplate(id, input)
    return c.json(template)
  } catch (err) {
    if (err instanceof TemplateNotFoundError) {
      return c.json({ error: 'Bicycle template not found', code: 'NOT_FOUND' }, 404)
    }

    console.error('[PATCH /bicycle-templates/:id] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /bicycle-templates/:id/deactivate — Soft-disable a template
// ===========================================================================

bicycleTemplatesRoutes.patch('/:id/deactivate', async (c) => {
  const id = c.req.param('id')

  try {
    await deactivateTemplate(id)
    return c.json({ success: true, message: 'Bicycle template deactivated' })
  } catch (err) {
    if (err instanceof TemplateNotFoundError) {
      return c.json({ error: 'Bicycle template not found', code: 'NOT_FOUND' }, 404)
    }

    console.error('[PATCH /bicycle-templates/:id/deactivate] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

export default bicycleTemplatesRoutes

import crypto from 'crypto'
import { db } from '@/db/index.js'
import { bicycleTemplates, type BicycleTemplate } from '@/db/schema.js'
import { and, eq, or, asc, count, sql } from 'drizzle-orm'

// ---------------------------------------------------------------------------
// DTO shapes returned by the API (compact catalog item + full detail)
// ---------------------------------------------------------------------------

export interface BicycleTemplateCatalogItem {
  id: string
  brand: string
  model: string
  basePriceNet?: number
}

/** Full template detail for create/edit forms (optional fields). */
export interface BicycleTemplateDetail {
  id: string
  brand: string
  model: string
  description?: string
  basePriceNet?: number
}

/** Response envelope for paginated catalog queries. */
export interface TemplatesCatalogResponse {
  templates: BicycleTemplateCatalogItem[]
  total: number
}

// ---------------------------------------------------------------------------
// Public API — Read operations
// ---------------------------------------------------------------------------

/**
 * Browse the active bicycle template catalog with optional search filtering.
 *
 * Search matches on `brand` or `model` (case-insensitive partial match).
 * Returns only active templates.
 */
export async function browseTemplates(search?: string): Promise<TemplatesCatalogResponse> {
  const [results, total] = await Promise.all([
    listTemplates(search),
    countTemplates(search)
  ])

  return {
    templates: results.map(toCatalogItem),
    total
  }
}

/**
 * Look up a single template by ID (active only).
 */
export async function getTemplateById(id: string): Promise<BicycleTemplateDetail | undefined> {
  const result = await findTemplateById(id)
  return result ? toTemplateDetail(result) : undefined
}

// ---------------------------------------------------------------------------
// Input types for write operations
// ---------------------------------------------------------------------------

export interface CreateBicycleTemplateInput {
  brand: string
  model: string
  description?: string
  basePriceNet?: number
}

// ---------------------------------------------------------------------------
// Public API — Write operations
// ---------------------------------------------------------------------------

/**
 * Create a new bicycle template.
 */
export async function createTemplate(input: CreateBicycleTemplateInput): Promise<BicycleTemplateDetail> {
  const id = crypto.randomUUID()
  const template = await repoCreateTemplate({
    id,
    brand: input.brand,
    model: input.model,
    description: input.description ?? null,
    basePriceNet: input.basePriceNet ?? null,
  })
  return toTemplateDetail(template)
}

/**
 * Update an existing template with partial data.
 */
export async function updateTemplate(id: string, input: Partial<Pick<BicycleTemplate, 'brand' | 'model' | 'description' | 'basePriceNet'>>): Promise<BicycleTemplateDetail> {
  if (Object.keys(input).length === 0) {
    throw new TemplateNotFoundError(id)
  }

  const template = await repoUpdateTemplate(id, input)
  return toTemplateDetail(template)
}

/**
 * Soft-disable a template by setting isActive to false.
 */
export async function deactivateTemplate(id: string): Promise<void> {
  await repoDeactivateTemplate(id)
}

// ---------------------------------------------------------------------------
// Repository layer — database access functions
// ---------------------------------------------------------------------------

/**
 * List active templates, optionally filtered by search term.
 */
async function listTemplates(search?: string): Promise<BicycleTemplate[]> {
  if (search) {
    const lowerSearch = search.toLowerCase()
    return db
      .select()
      .from(bicycleTemplates)
      .where(
        and(
          eq(bicycleTemplates.isActive, true),
          or(
            sql`LOWER(${bicycleTemplates.brand}) LIKE ${'%' + lowerSearch + '%'}`,
            sql`LOWER(${bicycleTemplates.model}) LIKE ${'%' + lowerSearch + '%'}`
          )
        )
      )
      .orderBy(asc(bicycleTemplates.brand), asc(bicycleTemplates.model))
  }

  return db
    .select()
    .from(bicycleTemplates)
    .where(eq(bicycleTemplates.isActive, true))
    .orderBy(asc(bicycleTemplates.brand), asc(bicycleTemplates.model))
}

/**
 * Count active templates, optionally filtered by search term.
 */
async function countTemplates(search?: string): Promise<number> {
  if (search) {
    const lowerSearch = search.toLowerCase()
    const [{ count: total }] = await db
      .select({ count: count() })
      .from(bicycleTemplates)
      .where(
        and(
          eq(bicycleTemplates.isActive, true),
          or(
            sql`LOWER(${bicycleTemplates.brand}) LIKE ${'%' + lowerSearch + '%'}`,
            sql`LOWER(${bicycleTemplates.model}) LIKE ${'%' + lowerSearch + '%'}`
          )
        )
      )

    return total
  }

  const [{ count: total }] = await db
    .select({ count: count() })
    .from(bicycleTemplates)
    .where(eq(bicycleTemplates.isActive, true))

  return total
}

/**
 * Find a single active template by ID.
 */
async function findTemplateById(id: string): Promise<BicycleTemplate | undefined> {
  const [result] = await db
    .select()
    .from(bicycleTemplates)
    .where(and(eq(bicycleTemplates.id, id), eq(bicycleTemplates.isActive, true)))

  return result ?? undefined
}

/**
 * Create a new template. Returns the created BicycleTemplate.
 */
async function repoCreateTemplate(templateData: { id: string; brand: string; model: string; description?: string | null; basePriceNet?: number | null }): Promise<BicycleTemplate> {
  const [created] = await db
    .insert(bicycleTemplates)
    .values({ ...templateData, isActive: true })
    .returning()

  return created
}

/**
 * Update template fields. Only active templates can be modified.
 */
async function repoUpdateTemplate(id: string, updates: Partial<Pick<BicycleTemplate, 'brand' | 'model' | 'description' | 'basePriceNet'>>): Promise<BicycleTemplate> {
  const [updated] = await db
    .update(bicycleTemplates)
    .set(updates)
    .where(eq(bicycleTemplates.id, id))
    .returning()

  if (!updated) throw new TemplateNotFoundError(id)

  return updated
}

/**
 * Soft-disable a template by setting isActive to false.
 */
async function repoDeactivateTemplate(id: string): Promise<void> {
  const result = await db
    .update(bicycleTemplates)
    .set({ isActive: false })
    .where(eq(bicycleTemplates.id, id))

  if (result.changes === 0) throw new TemplateNotFoundError(id)
}

// ---------------------------------------------------------------------------
// Helpers — map between DB entity and API DTO shapes
// ---------------------------------------------------------------------------

/** Map a BicycleTemplate entity to the catalog API response shape (compact). */
function toCatalogItem(template: BicycleTemplate): BicycleTemplateCatalogItem {
  return {
    id: template.id,
    brand: template.brand,
    model: template.model,
    basePriceNet: template.basePriceNet ?? undefined,
  }
}

/** Map a BicycleTemplate entity to the full detail shape (for create/edit). */
function toTemplateDetail(template: BicycleTemplate): BicycleTemplateDetail {
  return {
    id: template.id,
    brand: template.brand,
    model: template.model,
    description: template.description ?? undefined,
    basePriceNet: template.basePriceNet ?? undefined,
  }
}

// ---------------------------------------------------------------------------
// Error types
// ---------------------------------------------------------------------------

export class TemplateNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Bicycle template not found: ${id}`)
    this.name = 'TemplateNotFoundError'
  }
}

import * as React from 'react'
import { formatCentsToEuro } from '@/shared/lib/utils.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface CurrencyInputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'onChange' | 'value'> {
  /** Current value in cents (integer) */
  value: number
  /** Change callback — receives new value in cents */
  onChange: (cents: number) => void
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

/**
 * CurrencyInput — accepts decimal euros, converts to/from cents.
 *
 * Displays values as €X.XX but stores them internally as integer cents.
 * This prevents floating-point precision issues while providing a familiar
 * euro-formatted display for users.
 */
export function CurrencyInput({ value, onChange, className, ...props }: CurrencyInputProps) {
  const [displayValue, setDisplayValue] = React.useState(formatCentsToEuro(value))

  // Update display when cents change externally
  React.useEffect(() => {
    setDisplayValue(formatCentsToEuro(value))
  }, [value])

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const raw = e.target.value

    // Allow empty input during typing
    if (raw === '' || raw === '-') {
      onChange(0)
      return
    }

    // Parse decimal euros → cents
    const euroValue = parseFloat(raw.replace(',', '.'))
    if (isNaN(euroValue) || euroValue < 0) {
      return
    }

    const cents = Math.round(euroValue * 100)
    onChange(cents)
  }

  const handleBlur = () => {
    // Format to 2 decimal places on blur
    setDisplayValue(formatCentsToEuro(value))
  }

  return (
    <div className="relative">
      <input
        type="text"
        inputMode="decimal"
        value={displayValue}
        onChange={handleChange}
        onBlur={handleBlur}
        className={`h-10 w-full rounded-md border border-input bg-background pl-3 pr-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 ${className ?? ''}`}
        {...props}
      />
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/** Generate a unique ID for optimistic UI updates.
 * Works in both browser and Node.js without crypto.randomUUID(). */
export function generateId(): string {
  return Math.random().toString(36).substring(2) + Date.now().toString(36)
}

/** Format cents (integer) to Euro string with 2 decimal places. */
export function formatCentsToEuro(cents: number): string {
  return `€${(cents / 100).toFixed(2)}`
}

import { describe, it, expect, beforeEach } from 'vitest'
import app from '@/app.js'
import { db } from '@/db/index.js'
import { bicycleTemplates } from '@/db/schema.js'

describe('Bicycle Templates Routes', () => {
  async function resetTemplates() {
    await db.delete(bicycleTemplates)
  }

  beforeEach(async () => {
    await resetTemplates()
  })

  // ========================================================================
  // GET /api/bicycle-templates — Browse catalog (verify API contract unchanged)
  // ========================================================================

  describe('GET /api/bicycle-templates', () => {
    it('should return 200 with empty array when no templates exist', async () => {
      const res = await app.request('/api/bicycle-templates')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body).toEqual({ templates: [], total: 0 })
    })

    it('should return active templates with correct response shape', async () => {
      await db.insert(bicycleTemplates).values([
        { id: 't1', brand: 'Gazelle', model: 'Ultimate C8 HMB' },
        { id: 't2', brand: 'Batavus', model: 'Gold Crown' }
      ])

      const res = await app.request('/api/bicycle-templates')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.templates).toHaveLength(2)
      expect(body.total).toBe(2)

      // Verify response shape
      const template = body.templates[0]
