import { formatCentsToEuro } from '@/shared/lib/utils.js'
import { showSuccess, showError } from '@/shared/lib/notifications.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface BicycleTemplateCatalogItem extends Record<string, unknown> {
  id: string
  brand: string
  model: string
  basePriceNet?: number
}

interface BicycleTemplateDetail extends BicycleTemplateCatalogItem {
  description?: string
}

interface CreateBicycleTemplateInput {
  brand: string
  model: string
  description?: string
  basePriceNet?: number
}

interface UpdateBicycleTemplateInput {
  brand?: string
  model?: string
  description?: string
  basePriceNet?: number
}

// ---------------------------------------------------------------------------
// API helpers
// ---------------------------------------------------------------------------

async function fetchBicycleTemplates(search?: string): Promise<{ templates: BicycleTemplateCatalogItem[]; total: number }> {
  const url = search ? `/api/bicycle-templates?search=${encodeURIComponent(search)}` : '/api/bicycle-templates'
  const res = await fetch(url)
  if (!res.ok) throw new Error('Failed to fetch bicycle templates')
  return res.json()
}

async function createBicycleTemplate(input: CreateBicycleTemplateInput): Promise<BicycleTemplateDetail> {
  const res = await fetch('/api/bicycle-templates', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to create bicycle template')
  }
  return res.json()
}

async function updateBicycleTemplate(id: string, input: UpdateBicycleTemplateInput): Promise<BicycleTemplateDetail> {
  const res = await fetch(`/api/bicycle-templates/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to update bicycle template')
  }
  return res.json()
}

async function deactivateBicycleTemplate(id: string): Promise<void> {
  const res = await fetch(`/api/bicycle-templates/${id}/deactivate`, { method: 'PATCH' })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to deactivate bicycle template')
  }
}

